package db

import (
	"database/sql"
	"fmt"
)

// The AI layer of a note, cached.
//
// A card summary is generated by the configured chat model, and generating one
// per card on every page load would be both slow and expensive. The table keeps
// the last summary and its keywords so the read path (a card grid) is a plain
// indexed lookup: no model call, no latency. content_hash is what makes the
// cache honest — a note edited after its summary was written still shows the
// old text, but flagged as stale instead of pretending it is current.
//
// No backfill: an empty table means "no summaries generated yet", which is the
// truth for every existing note.
var noteInsightsDDL = []string{
	`CREATE TABLE IF NOT EXISTS note_insights (
		note_id INTEGER PRIMARY KEY,
		content_hash TEXT NOT NULL,
		summary TEXT NOT NULL DEFAULT '',
		keywords TEXT NOT NULL DEFAULT '',
		updated_at DATETIME DEFAULT CURRENT_TIMESTAMP,
		FOREIGN KEY (note_id) REFERENCES project_notes(id) ON DELETE CASCADE
	)`,
}

// EnsureNoteInsights creates the note_insights cache table (schema v33).
func EnsureNoteInsights(database *sql.DB) error {
	for _, stmt := range noteInsightsDDL {
		if _, err := database.Exec(stmt); err != nil {
			if isAlreadyExistsErr(err) {
				continue
			}
			return fmt.Errorf("create note_insights: %w", err)
		}
	}
	return nil
}

// NoteInsightRow is one cached summary row.
type NoteInsightRow struct {
	NoteID      int64
	ContentHash string
	Summary     string
	Keywords    string
}

// ListNoteInsights returns every cached row keyed by note id. The table holds
// one small row per summarized note, so the whole map is cheaper than a query
// per visible card.
func ListNoteInsights(database *sql.DB) (map[int64]NoteInsightRow, error) {
	rows, err := database.Query("SELECT note_id, content_hash, summary, keywords FROM note_insights")
	if err != nil {
		return nil, fmt.Errorf("list note insights: %w", err)
	}
	defer rows.Close()
	out := map[int64]NoteInsightRow{}
	for rows.Next() {
		var r NoteInsightRow
		if err := rows.Scan(&r.NoteID, &r.ContentHash, &r.Summary, &r.Keywords); err != nil {
			return nil, err
		}
		out[r.NoteID] = r
	}
	return out, rows.Err()
}

// PutNoteInsight upserts one summary. The hash is stored with it so a later
// read can tell a current summary from one whose note has since changed.
func PutNoteInsight(database *sql.DB, noteID int64, contentHash, summary, keywords string) error {
	_, err := database.Exec(
		`INSERT INTO note_insights(note_id, content_hash, summary, keywords, updated_at)
		 VALUES(?, ?, ?, ?, CURRENT_TIMESTAMP)
		 ON CONFLICT(note_id) DO UPDATE SET
		   content_hash = excluded.content_hash,
		   summary = excluded.summary,
		   keywords = excluded.keywords,
		   updated_at = CURRENT_TIMESTAMP`,
		noteID, contentHash, summary, keywords)
	if err != nil {
		return fmt.Errorf("put note insight %d: %w", noteID, err)
	}
	return nil
}

// DeleteNoteInsight drops one cached summary (note deleted, or its generation
// was explicitly discarded).
func DeleteNoteInsight(database *sql.DB, noteID int64) error {
	_, err := database.Exec("DELETE FROM note_insights WHERE note_id = ?", noteID)
	return err
}
